+
+	f := &fakeSeq{outs: []string{threads, page2, page3}}
+	c := &Client{dir: "/repo", repo: "kukv/octoscope", run: f.run}
+
+	rc, err := c.PRReviewContext(t.Context(), "", 55)
+	if err != nil {
+		t.Fatalf("PRReviewContext: %v", err)
